(function(){
  const searchInput = document.getElementById('search') || document.getElementById('js-search');
  const catBtns = document.querySelectorAll('.js-cat[data-cat], [data-js-cat]');
  const grid = document.getElementById('grid') || document.getElementById('js-grid');
  const countEl = document.getElementById('count') || document.getElementById('js-count');
  if (!grid) return;

  let activeCat = 'all';
  const cards = Array.from(grid.querySelectorAll('.js-card'));

  function toAssameseNum(n) {
    const map = {'0':'০','1':'১','2':'২','3':'৩','4':'৪','5':'৫','6':'৬','7':'৭','8':'৮','9':'৯'};
    return String(n).replace(/[0-9]/g, m => map[m]);
  }

  function applyFilter() {
    const q = (searchInput ? searchInput.value : '').trim().toLowerCase();
    let visible = 0;
    cards.forEach(card => {
      const cCat = card.getAttribute('data-category') || 'all';
      const cSearch = (card.getAttribute('data-search') || card.textContent || '').toLowerCase();
      const catMatch = (activeCat === 'all') || (cCat === activeCat);
      const qMatch = !q || cSearch.includes(q);
      if (catMatch && qMatch) {
        card.style.display = '';
        visible++;
      } else {
        card.style.display = 'none';
      }
    });
    if (countEl) {
      countEl.textContent = toAssameseNum(visible) + 'টা লেখা';
    }
  }

  catBtns.forEach(btn => {
    btn.addEventListener('click', function() {
      activeCat = this.getAttribute('data-cat') || this.getAttribute('data-js-cat') || 'all';
      catBtns.forEach(b => b.classList.toggle('active', b === this));
      applyFilter();
    });
  });

  if (searchInput) {
    searchInput.addEventListener('input', applyFilter);
  }
})();
